@Component
export struct ProfileScreen {
  build() {
    Column() { Text('bodybuilder profile') }
    .padding(12)
    .backgroundColor(Color.White)
    .width(180)
  }
}

import { TrainingPalette } from './TrainingPalette'
@Component
export struct ProfileTile {
  @Builder
  renderTile() {
    Row() { Text('bodybuilder profile') }
    .padding(12)
    .backgroundColor(TrainingPalette.surface)
    .width(180)
  }
  build() { this.renderTile() }
}

export class TrainingPalette {
  static surface: string = '#eeeeee'
}

